package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamFolkSongsBank1 {
    private const val T = "ශ්‍රී ලාංකේය ජන සංගීතය හා ජන ගී"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ශ්‍රී ලාංකේය ජන සංගීතයේදී 'ජන ගීය' නිර්මාණය වී ඇත්තේ කවර සමාජ අවශ්‍යතාවක් මතද?", "ගැමි ජනතාවගේ එදිනෙදා ශ්‍රමය, වෙහෙස සහ හැඟීම් ප්‍රකාශ කිරීමට", "රාජ සභාවේ විදේශීය තානාපතිවරුන් පිළිගැනීමට", "විශ්වවිද්‍යාල විභාග ප්‍රශ්න පත්‍ර සැකසීමට", "රජයේ මුදල් අයවැය ප්‍රකාශයට පත් කිරීමට", "ගොවිතැන්, පාරු පැදීම වැනි ජීවන අරගලයේදී ගැමි හදවතින් ජන ගී බිහි විය."),
        q("දේශීය ජන ගී බොහොමයක කැපී පෙනෙන සුවිශේෂී සංගීත ලක්ෂණය කුමක්ද?", "ස්වර 3 ක් හෝ 4 ක් අතර දෝලනය වන සරල තනු රටාව", "සප්තක 3ම ආවරණය කරන ද්‍රුත තාන් යෙදීම", "තීව්‍ර මධ්‍යමය සමඟ කෝමල ස්වර 4ක්ම යෙදීම", "සැමවිටම විලම්බිත ඒක්තාලයෙන් පමණක් ගැයීම", "සීමිත ස්වර පරාසයක් තුළ ප්‍රබල භාව රසයක් මැවීම ජන ගීයේ අනන්‍යතාවයි."),
        q("රාත්‍රී කාලයේ හේන් සහ කුඹුරු වන සතුන්ගෙන් රැකගැනීමේදී පාළුව හා බිය දුරු කර ගැනීමට ගැයූ ජන ගී කවරේද?", "පැල් කවි", "පාරු කවි", "ගොයම් කවි", "බම්බර කවි", "පැලෙහි සිට දීර්ඝ ඇදීම් සහිතව ගයන පැල් කවි රාත්‍රී නිහඬතාව බිඳලයි."),
        q("'පැලේ පැලී පැල්පත් වල ලගින්නා' යන ජන කවිය අයත් වන ජන ගී වර්ගය කුමක්ද?", "පැල් කවි", "කරත්ත කවි", "පතල් කවි", "නෙළුම් කවි", "හේන් රැකීමේ දුෂ්කර ජීවිතය හා බැඳි මෙය ප්‍රකට පැල් කවියකි."),
        q("පැල් කවි ගායනයේදී ගැමියන් උස් හඬින් දීර්ඝ ඇදීම් (Melismatic singing) යොදාගැනීමට හේතුව කුමක්ද?", "වන සතුන් පලවා හැරීමට හා අනෙක් පැල්කරුවන් සමඟ සන්නිවේදනයට", "තබ්ලාවේ ත්‍රිතාලයට සමාන කිරීමට", "නූර්ති වේදිකාවේ පේළි පිරවීමට", "රාග බිලාවල් ස්වර පුහුණු වීමට", "විශාල හඬකින් රාත්‍රී අඳුර තුළ දුරට ඇසෙන සේ ගැයීම ප්‍රායෝගික අවශ්‍යතාවක් විය."),
        q("කැලණි ගඟ, කළු ගඟ ආදී ගංගා ඔස්සේ භාණ්ඩ ප්‍රවාහනය කළ තොටියන් ගැයූ ජන කවි මොනවාද?", "පාරු කවි", "කරත්ත කවි", "ගොයම් කවි", "ඔන්චිලි වාරම්", "ගඟේ තරංග චලනයට හා රිට ගැසීමේ රිද්මයට පාරු කවි ගැයුණි."),
        q("'ඔන්න මලේ ඔය නාමල නෙළා වරෙන්' යන ගීතය ගැයූ තොටියන්ගේ ගායන රටාවේ විශේෂත්වය කුමක්ද?", "දිය රළේ ගමන මෙන් සෙමෙන් ඇදී යන මධුර රිද්මය", "වේගවත් රණ ගී තාලයක් තිබීම", "පඛාවජ් වාදනය සමඟ ගැයීම", "බටහිර ස්ටාෆ් සටහන් අනුගමනය කිරීම", "පාරු කවිවල නාද රටාව ගඟේ ගැලීමේ ස්වභාවය පිළිබිඹු කරයි."),
        q("ඈත පළාත්වල සිට බර පටවාගෙන ගමන් ගත් කරත්තකරුවන් විසින් ගයන ලද ජන ගී විශේෂය කුමක්ද?", "කරත්ත කවි", "පතල් කවි", "පැල් කවි", "දරු නැළවිලි", "කරත්ත රෝදය කැරකෙන රිද්මය හා ගවයා කෙරෙහි අනුකම්පාව මෙහි තේමා වේ."),
        q("'තණ්ඩලේ දෙන්නා දෙපලේ බැඳලා' යන ප්‍රසිද්ධ කවිය අයත් වන්නේ කුමන ජන ගී කොටසටද?", "කරත්ත කවි", "ගොයම් කවි", "පාරු කවි", "පැල් කවි", "හපුගල ආදී කඳු නැඟීමේදී ගවයින් විඳින දුක මෙම කරත්ත කවියෙන් කියැවේ."),
        q("මැණික් හෝ මිනිරන් පතල් තුළ වැඩ කරන කම්කරුවන් අන්තරාය හා වෙහෙස නිවා ගැනීමට ගැයූ කවි මොනවාද?", "පතල් කවි", "බම්බර කවි", "නෙළුම් කවි", "වන්නම් කවි", "දුම්බර කෙතේ කළු මැණිකෝ වැනි ගී පතල් ජීවිතයේ දුක ප්‍රකාශ කරයි."),
        q("'ඉන්නේ දුම්බරයි මහ කළු ගලක් යට' යන ජන කවියෙන් කියැවෙන්නේ කවර කම්කරු පිරිසකගේ ජීවිතයද?", "පතල් කම්කරුවන්ගේ ජීවිතය", "පාරු තොටියන්ගේ ජීවිතය", "කරත්තකරුවන්ගේ ජීවිතය", "ධීවරයින්ගේ ජීවිතය", "පොළොව යට දුෂ්කර පතල් කැණීමේදී දැනෙන බිය හා වේදනාව මෙහි ගැබ්වේ."),
        q("කුඹුරේ ගොයම් පැළ සිටුවීමේදී (ගොයම් නෙළීමේදී) කාන්තාවන් සමූහ වශයෙන් ගයන ජන ගී කවරේද?", "නෙළුම් කවි", "පැල් කවි", "පතල් කවි", "බම්බර කවි", "සමූහ ශ්‍රමය සමඟ එක්ව තාලයට ගොයම් නෙළීමේදී නෙළුම් කවි ගැයේ."),
        q("පැසුණු ගොයම් කැපීමේදී දෑකැති අතින් ගත් ගැමියන් එකමුතුව ගයන ජන ගී විශේෂය කුමක්ද?", "ගොයම් කවි", "ඔන්චිලි වාරම්", "රබන් පද", "කරත්ත කවි", "කමත් හා ගොයම් කැපීමේ රිද්මයට ගොයම් කවි මනාව ගැළපේ."),
        q("මහා කඳු බෑවුම්වල උස් ගස්වලට හෝ ගල් පර්වතවලට නැඟ පැණි කැපීමේදී ගැයෙන ජන කවි කවරේද?", "බම්බර කවි", "පැල් කවි", "පාරු කවි", "කලගෙඩි කවි", "ගසේ හෝ වැලේ එල්ලී සිටින අයගේ ආරක්ෂාව හා බිය දුරු කිරීමට බම්බර කවි ගැයේ."),
        q("බම්බර කවි ගායනයේදී ගැමියන් විශේෂයෙන්ම ප්‍රාර්ථනා කරන හෝ අයැදින කාරණය කුමක්ද?", "දෙවියන්ගේ රැකවරණය සහ පවුලේ සෙනෙහස", "වැඩි කුලී මුදලක් ඉල්ලීම", "රජතුමාගෙන් ඉඩම් තෑගි පැතීම", "නැව් වලින් විදේශ ගතවීම", "ජීවිත අවදානම නිසා දේව ආරක්ෂාව පැතීම බම්බර කවිවල ප්‍රධාන තේමාවකි."),
        q("සිංහල අලුත් අවුරුදු සමයේදී ඔන්චිලි පදින විට සතුට ප්‍රකාශ කරමින් ගයන ජන ගී විශේෂය කුමක්ද?", "ඔන්චිලි වාරම්", "පතල් කවි", "පැල් කවි", "නාඩගම් සින්දු", "පත්තිනි දේව වන්දනාව හා බැඳුණු ඔන්චිලි වාරම් තාලයට ගැයේ."),
        q("අවුරුදු උත්සව හා විනෝද අවස්ථාවලදී බංකු රබාන වටා සිට කාන්තාවන් වයමින් ගයන කෙටි රිද්ම පද මොනවාද?", "රබන් පද", "පැල් කවි", "කරත්ත කවි", "පාරු කවි", "රබන් සුරල් හා රබන් පද වේගවත් මාත්‍රා චලනයන්ගෙන් යුක්තය."),
        q("'දොං තකිට තක දොං - උඩ පැන පැන දොං' වැනි රචනා අයත් වන්නේ කුමන ජන සංගීත අංගයටද?", "රබන් පද", "පැල් කවි", "දරු නැළවිලි", "නූර්ති ගී", "රබානේ නාදය අනුකරණය කරමින් රබන් පද නිර්මාණය වී ඇත."),
        q("කුඩා දරුවන් නැළවීම සඳහා මව්වරුන් විසින් මෘදු ලයකින් ගයන ජන ගී කොටස හඳුන්වන්නේ කෙසේද?", "දරු නැළවිලි ගී (තොටිලි ගී)", "බම්බර කවි", "කරත්ත කවි", "පතල් කවි", "සම ස්වර හා සන්සුන් රිද්මයෙන් 'දොයි දොයි දොයිය බබා' ආදිය ගැයේ."),
        q("මහනුවර යුගයේ රජ සභාවේ 'කවිකාර මඩුව' තුළ ප්‍රචලිත වූ සම්භාව්‍ය දේශීය ගීත හා නර්තන අංගය කුමක්ද?", "වන්නම් ගායනා (දහඅට වන්නම)", "නූර්ති ගී", "පැල් කවි", "බම්බර කවි", "සතුන්ගේ හා දේව චරිතවල ගමන් විලාස වර්ණනා කරමින් වන්නම් 18ක් රචනා විය."),
        q("සිංහල වන්නම් ගායනා කිරීමේදී ගායකයා හා බෙර වාදකයා මුලින්ම වාදනය කර ගයන තාලය හා පද මාලාව කුමක්ද?", "තානම හා කවිය (සහ කස්තිරම)", "සර්ගම් හා තානය", "දුගුන් හා චෞගුන්", "ඛාලි හා මුඛ්ඩාව", "සෑම වන්නමක්ම තානමෙන් ඇරඹී කවිය, කස්තිරම, සීරුමාරුව සහ අඩව්වෙන් නිමා වේ."),
        q("වන්නමක කවිය ගැයීමට පෙර කිසිදු වචන අර්ථයක් නොමැතිව 'තන න තනම් දන' ආදී ලෙස ගැයෙන රිද්මයානුකූල නාද කොටස කුමක්ද?", "තානම", "සීරුමාරුව", "අඩව්ව", "පැල් කවිය", "වන්නමේ ස්වර රටාව හා තාල ගතිය පෙන්වන්නේ තානම මඟිනි."),
        q("රජුගේ හෝ උතුමන්ගේ ගුණ වර්ණනා කිරීම සඳහා පැරණි කවිකාර මඩුවේදී ගැයූ වීර හා ප්‍රශංසා ගීත මොනවාද?", "ප්‍රශස්ති ගීත", "නැළවිලි ගීත", "පතල් කවි", "ඔන්චිලි වාරම්", "නරේන්ද්‍රසිංහ, රාජසිංහ වැනි රජවරුන් වෙනුවෙන් පවන, ශ්‍රී නාමය වැනි ප්‍රශස්ති ගැයුණි."),
        q("සතුරු යුද ජයග්‍රහණ හෝ වීර ක්‍රියා වර්ණනා කරමින් වේගවත් රිද්මයෙන් ගැයූ පැරණි දේශීය ගීත කවරේද?", "හටන් කවි", "පැල් කවි", "කරත්ත කවි", "බම්බර කවි", "සීතාවක හටන, ඉංග්‍රීසි හටන වැනි කාව්‍ය හටන් කවි ගණයට වැටේ."),
        q("ශ්‍රී ලංකාවේ ජන ගී පිළිබඳ විද්‍යාත්මක සංගීත පර්යේෂණ සිදු කර ග්‍රන්ථ ගණනාවක් රචනා කළ ප්‍රවීණ විද්වතා කවුද?", "සී. ද එස්. කුලතිලක මහතා", "පණ්ඩිත් භාත්ඛණ්ඩේ", "මියාන් තාන්සේන්", "පණ්ඩිත් රවි ශංකර්", "දේශීය ජන ගී ස්වර විශ්ලේෂණය හා ලේඛනගත කිරීම කුලතිලක මහතාගේ ප්‍රමුඛ මෙහෙවරයි."),
        q("'හෙළ ගී මග' වැනි කෘති රචනා කරමින් දේශීය ජන නාද රටා පදනම් කරගත් පාසල් සංගීතයක් ගොඩනැගූ විද්වතා කවුද?", "ඩබ්ලිව්. බී. මකුලොළුව මහතා", "ජෝන් ද සිල්වා මහතා", "විශ්වනාත් ලෞජි මහතා", "අමීර් ඛුස්රෝ", "මකුලොළුව මහතා ජන සංගීතය පාසල් විෂය මාලාවට ගෙන ඒමට විශාල වැඩ කොටසක් කළේය."),
        q("මකුලොළුව මහතා විසින් සිංහල ජන ගී හා නාද රටා ඇසුරෙන් නිර්මාණය කළ ප්‍රකට ගීත නාටකය කුමක්ද?", "දෙපානෝ", "මනමේ", "සිරිසඟබෝ", "වෙස්සන්තර", "දේශීය ජන ගී සංගීතය මත පදනම්ව 'දෙපානෝ' සහ 'හෙළ මිහිර' නිර්මාණය විය."),
        q("දේශීය ජන ගීවල 'සිව්පද' ආකෘතිය යනුවෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "සෑම කවියක්ම සමාන මාත්‍රා හෝ එළිවැට සහිත පද 4 කින් යුක්ත වීම", "කවියක වචන 4ක් පමණක් තිබීම", "වාද්‍ය භාණ්ඩ 4ක් එකට වැයීම", "රාග 4කින් කවිය ගැයීම", "බොහෝ පැල්, පාරු හා ගොයම් කවි සම්ප්‍රදායික සිව්පද ආකෘතියෙන් රචිතය."),
        q("ගොවිතැන් කටයුතුවලදී කමත තුළ පවතින භාෂාව සහ චාරිත්‍ර හා බැඳුණු ගායනා හඳුන්වන්නේ කුමන නමින්ද?", "කමත් කවි සහ අඬහැර", "නූර්ති ගී", "රබන් සුරල්", "තාරානා", "වී මැඩීමේදී ගොනුන් දැක්කීම සඳහා ගැමියෝ අඬහැර හා කමත් කවි ගයති."),
        q("මුහුදුබඩ ප්‍රදේශවල මාදැල් අදින ධීවර ජනතාව එක්ව කඹය ඇදීමේදී රිද්මය ලබා ගැනීමට ගයන ගීත මොනවාද?", "අම්බා ගී හෙවත් ධීවර කවි (හෝයි පද)", "බම්බර කවි", "පතල් කවි", "පැල් කවි", "ශ්‍රම එකමුතුකම පවත්වා ගැනීමට 'හේලේ හෙයියා' වැනි තාල ගී ධීවරයෝ ගයති."),
        q("දේශීය ජන ගී ගායනයේදී බොහෝ විට බෙර හෝ වෙනත් වාද්‍ය භාණ්ඩ භාවිත නොකරන්නේ කුමන කවි වර්ගයේදීද?", "පැල් කවි, පාරු කවි සහ කරත්ත කවි", "රබන් පද සහ කළගෙඩි ගී", "වන්නම් සහ හේවිසි", "නාඩගම් සහ නූර්ති ගී", "රැකියාවේ ස්වභාවය නිසා පැල්, පාරු හා කරත්ත කවි නිදහස් කටහඬින් පමණක් ගැයේ."),
        q("ගැමි කාන්තාවන් කළගෙඩි රැගෙන ගඟට යන අවස්ථා නිරූපණය කරමින් නර්තනය සමඟ ගයන ජන ගී කවරේද?", "කළගෙඩි ගී (කළගෙඩි මාලය)", "පතල් කවි", "බම්බර කවි", "හටන් කවි", "වයඹ හා මධ්‍යම පළාත්වල ගැමි කතුන් තාලයට කළගෙඩි නටමින් මෙම ගී ගයති."),
        q("පහතරට හා උඩරට ප්‍රදේශවල 'රබන් නැටුම' හා සමඟාමීව වී පෙළීමේදී කාන්තාවන් ගයන කවි විශේෂය කුමක්ද?", "කුලු කවි", "කරත්ත කවි", "පාරු කවි", "හේන් පැල් කවි", "කුලුවලින් වී පෙළීමේ ශ්‍රමය සමඟ කුලු ගීත ගායනා කෙරේ."),
        q("ලී කෙළි නැටුම ඉදිරිපත් කිරීමේදී ගායනයට සමගාමීව රිද්මය රකින්නේ කුමකින්ද?", "දෙඅතේ ඇති ලී කැබලි එකිනෙක ගැටීමෙන්", "තබ්ලා හා සිතාර් වාදනයෙන්", "හාමෝනියමය වැයීමෙන්", "හක්ගෙඩිය පිඹීමෙන්", "කවියේ තාලයට අනුව ලී කෙළි ශබ්දය මුසු කරමින් ගැමියෝ නටති."),
        q("පැරණි දේශීය ජන ගීවල එන 'විලම්බිත ඇදීම' හෙවත් දීර්ඝ ස්වර දෝලනය වඩාත් හොඳින් අසන්නට ලැබෙන්නේ කුමන කවියකද?", "කරත්ත හා පැල් කවිවල", "රබන් පදවල", "ලී කෙළි කවිවල", "සරල ළමා ගීතවල", "රාත්‍රී නිහඬතාවේ හා මහා මග තනිකමේදී දීර්ඝව ස්වර ඇද ගයති."),
        q("ගැමි ගීතවල බොහෝ විට පදය අවසානයේ හෝ මැද 'ඔයේ', 'ආනේ', 'තන තනා' වැනි පද එක් කර ගැයීමෙන් සිදුවන්නේ කුමක්ද?", "තාලය හා ගායන ප්‍රවාහය අඛණ්ඩව පවත්වා ගැනීම", "කවියේ තේරුම සම්පූර්ණයෙන් වෙනස් කිරීම", "රාගයේ කෝමල ස්වර ඉවත් කිරීම", "බෙර වාදනය නැවැත්වීම", "පද විරාම පිරවීමට සහ රසය වැඩි කිරීමට මෙම අනුපූරක පද යොදයි."),
        q("ගායකයෙකු ජන කවියක් ගයන විට උත්තර භාරතීය ශාස්ත්‍රීය 'තාන්' හා 'මූර්කි' අධිකව යෙදීම නුසුදුසු වන්නේ ඇයි?", "ජන ගීයේ අව්‍යාජ සරල දේශීය ඌරුව නැති වන බැවින්", "තාලයේ මාත්‍රා 16ක් වෙනස් වන බැවින්", "කටහඬ වෙහෙසට පත්වන බැවින්", "වාද්‍ය භාණ්ඩ සුසර බිඳෙන බැවින්", "ජන ගී ගැයිය යුත්තේ ඊට ආවේණික සරල ගැමි නාද රටාව රැකෙන පරිදිය."),
        q("බෞද්ධ සාහිත්‍යමය පසුබිම සහිත ජාතක කතා පදනම් කරගෙන ගැමි ජනයා අතර ගැයුණු කාව්‍ය ගීත මොනවාද?", "වෙස්සන්තර කවි සහ යසෝදරාවත", "නූර්ති ගීත", "බයිලා සහ කපිරිඤ්ඤා", "චිත්‍රපට ගීත", "පින්කම් ගෙවල්වල හා විවේක වේලාවල තුන් සරණය, යසෝදරාවත හා වෙස්සන්තර කවි ගැයේ."),
        q("වැදි ජනතාව හෙවත් ආදිවාසීන්ගේ සාම්ප්‍රදායික නැටුම් හා යාතුකර්ම අතර ප්‍රකට ගායනා විශේෂය කුමක්ද?", "කිරිකොරහ යාග ගායනා", "පැල් කවි", "කරත්ත කවි", "නූර්ති ගී", "දඩයම සාර්ථක කර ගැනීමට හා ආරක්ෂාව පතා කිරිකොරහ ශාන්තිකර්මයේදී ගී ගයයි."),
        q("මලය රටේ හෙවත් වතුකර ජන සංගීතයේ නෙළුම් සහ තේ දළු නෙළීම හා බැඳුණු සාමූහික ජන ගී කුමන සංස්කෘතියකට අයත්ද?", "දෙමළ ජන සංගීත සම්ප්‍රදායට", "පෘතුගීසි සංගීත සම්ප්‍රදායට", "භාරතීය ධෲපද් සම්ප්‍රදායට", "බටහිර ජෑස් සම්ප්‍රදායට", "කාවඩි, කෝලාට්ටම් හා තේ වතු ශ්‍රම ගීත මෙරට දෙමළ ජන සංගීතය පෝෂණය කරයි."),
        q("ශ්‍රී ලංකාවේ කතෝලික ජන සංස්කෘතිය තුළ ජේසුස් වහන්සේගේ දුක් ප්‍රාප්තිය අලලා ගැයෙන සාම්ප්‍රදායික ගායනා මොනවාද?", "පසන් ගී", "පැල් කවි", "නෙළුම් කවි", "වන්නම් කවි", "ජාකෝමේ ගොන්සාල්වෙස් පියතුමන් ආදීන්ගේ දායකත්වයෙන් පසන් ගායනා මෙරට මුල් බැස ගත්තේය."),
        q("ජාකෝමේ ගොන්සාල්වෙස් පියතුමන් විසින් සිංහල කතෝලික සංගීතයට හඳුන්වා දුන් ප්‍රකට සාම්ප්‍රදායික ගීත සම්ප්‍රදාය කුමක්ද?", "පසන් සහ කන්තාරු ගී", "ගොයම් සහ නෙළුම් කවි", "නූර්ති සහ නාඩගම් ගී", "බම්බර සහ පතල් කවි", "දේශීය නාද රටා ඇසුරින් ක්‍රිස්තියානි භක්ති ගීත සාහිත්‍යයක් එතුමා ගොඩනැගීය."),
        q("ශ්‍රී ලංකාවේ මැලේ සහ පෘතුගීසි සම්භවයක් ඇති ජන කොටස් තුළින් මෙරට ජන සංගීතයට එක්වූ ප්‍රීතිමත් රිද්මය කුමක්ද?", "කපිරිඤ්ඤා සහ බයිලා", "වන්නම් සහ ප්‍රශස්ති", "පැල් කවි සහ පාරු කවි", "ශාන්තිකර්ම යාතිකා", "පෘතුගීසි හා අප්‍රිකානු සංස්කෘතික ආභාසයෙන් කපිරිඤ්ඤා ජන ගී රටාව ලැබිණි."),
        q("දකුණු ලංකාවේ 'ගාලු කොටුව' සහ 'මීගමුව' වැනි ප්‍රදේශවල කපිරිඤ්ඤා ගායනයේදී බහුලව යොදාගත් වාද්‍ය භාණ්ඩ මොනවාද?", "රබාන, වයලීනය, ගිටාරය හා ඩොල්කිය", "තබ්ලාව සහ සිතාරය", "ගැටබෙරය සහ හොරණෑව", "තම්බුරාව සහ පඛාවජය", "6/8 රිද්මයට වයලීන, මැන්ඩලින් හා රබන් සමඟ කපිරිඤ්ඤා ගැයේ."),
        q("ජන ගී ආශ්‍රයෙන් නූතන ශ්‍රී ලාංකේය සරල ගී සංගීතය නිර්මාණය කිරීමේදී පුරෝගාමී වූ ප්‍රවීණයන් අතර පළමු පෙළේ සිටින දෙදෙනෙක් නම් කරන්න.", "ඩබ්ලිව්. ඩී. අමරදේව සහ සුනිල් ශාන්ත", "මියාන් තාන්සේන් සහ අමීර් ඛුස්රෝ", "පණ්ඩිත් භාත්ඛණ්ඩේ සහ පලුස්කර්", "බිස්මිල්ලා ඛාන් සහ රවි ශංකර්", "දේශීය ජන ගීවල ජීව ගුණය නවීන සරල ගීයට ගෙන ඒමට ඔවුහු ක්‍රියා කළහ."),
        q("ගොවි බිමේ සාමූහික ශ්‍රමය අඩු වී වෙහෙස අමතක කිරීම සඳහා ගැයුණු ගීත සාමාන්‍යයෙන් හඳුන්වන පොදු නාමය කුමක්ද?", "ශ්‍රම ගී (Work Songs)", "වේදිකා නාට්‍ය ගී", "චිත්‍රපට පසුබිම් ගී", "රාජ සභා ප්‍රශස්ති", "ගොයම්, නෙළුම්, පාරු, පතල් ආදිය ශ්‍රම ගී ගණයට අයත් වේ."),
        q("'සවරම්' හා 'කුලු' නැටුම් සඳහා වාදනය කරනු ලබන ප්‍රධාන සංගීත භාණ්ඩය කුමක්ද?", "ගැටබෙරය හෝ රබාන (සහ තාලම්පට)", "සිතාරය", "වයලීනය", "සන්තූරය", "ගැමි ජන නැටුම් සඳහා දේශීය අවනද්ධ බෙර වර්ග සහ තාලම්පට වැයේ."),
        q("පිරිත් දේශනා, ජයමංගල ගාථා සහ මඟුල් බෙර නාද රටාවන්ගෙන් ජන සංගීතයට ලැබී ඇති බලපෑම කුමක්ද?", "ශාන්ත, මංගලමය හා පූජනීය නාද ලක්ෂණ එක් වීම", "වේගවත් නූතන රොක් රිද්ම ලැබීම", "බටහිර ස්ටාෆ් සංකේත නිර්මාණය වීම", "ථාට 10 ක්‍රමය බිහි වීම", "බෞද්ධ සංස්කෘතික පසුබිම දේශීය නාද රටාවල ස්වර භාවිතයට බලපෑවේය."),
        q("උඩරට පැල් කවි ගායනයේදී ගොවියන් 'ඕ... හෝ...' හෝ 'ඇයි මේ...' වැනි දිගු හඬ නැගීම් යොදාගන්නේ ඇයි?", "හුදෙකලාව මකාගෙන වන සතුන් පලවා හැරීමට හා සහෘදයන් ඇමතීමට", "වේගවත් තාලයක් ගණන් කිරීමට පමණක්", "නාඩගම් රංගනයක් පැවැත්වීමට", "විදේශීය සංචාරකයන් ආකර්ෂණය කිරීමට", "රාත්‍රී පැල් රැකීමේදී ඈත සිටින සෙසු ගොවියන් සමඟ සන්නිවේදනයට මෙම දිගු ඇදීම් යොදාගනී."),
        q("'ඉරට මුවාවෙන් ඉඳගෙන හිස පීරනවා' වැනි අලංකාර උපමා බහුලව දැකිය හැකි ජන කවි විශේෂය කුමක්ද?", "නෙළුම් කවි හා ගොයම් කවි", "නාඩගම් ඉන්නිස කවි", "පාර්සි නූර්ති ගී", "රාජ සභා ප්‍රශස්ති", "ස්වභාවධර්මයේ සුන්දර දසුන් හා කාන්තා සුන්දරත්වය ගොයම් හා නෙළුම් කවිවල වර්ණනා වේ."),
        q("'කන්ද උඩින් එන කිකිළිය ගමන බලා' වැනි ගැමි කවිවලින් පිළිබිඹු වන සමාජ අංශය කුමක්ද?", "ගැමි කෙළිලොල් බව හා උපහාස රසය", "රාජ්‍ය පාලන නීතිරීති", "විදේශීය යුද ශිල්පය", "නාගරික කර්මාන්තශාලා ජීවිතය", "ජන කවියේ එන හාස්‍ය හා සුන්දර නිරීක්ෂණ මෙවැනි කවිවලින් මතුවේ."),
        q("මහනුවර යුගයේ 'කවිකාර මඩුවේ'දී රජතුමාගේ තේජස හා ගුණ වර්ණනා කරමින් ගැයූ ගීත හඳුන්වන්නේ කෙසේද?", "ප්‍රශස්ති ගීත", "පැල් කවි", "පතල් කවි", "බම්බර කවි", "රාජ සභාවේ ගැයූ ප්‍රශස්ති ගීත සිංහල ශාස්ත්‍රීය කාව්‍ය සංගීත සම්ප්‍රදායේ කොටසකි."),
        q("ප්‍රශස්ති ගීත සංග්‍රහයන් අතර සුවිශේෂී ස්ථානයක් ගන්නා 'පවන' හා 'ශෘංගාරාලංකාරය' අයත් වන්නේ කවර යුගයකටද?", "මහනුවර යුගයට", "අනුරාධපුර යුගයට", "පොළොන්නරු යුගයට", "21 වන සියවසට", "සීතාවක හා මහනුවර යුගවල රජවරුන් අබියස ගැයීමට ප්‍රශස්ති හා හටන් කවි ලියැවිණි."),
        q("'ගජගා වන්නම' ගායනා කිරීමේදී ඉන් මූර්තිමත් කෙරෙන සත්ත්වයා සහ රසය කුමක්ද?", "ඇතුගේ ගාම්භීර ගමන හා වීර/ශාන්ත රසය", "සිංහයාගේ කෝපය", "මොනරාගේ වේගවත් පැනීම", "කුරුල්ලාගේ පියාසැරිය", "දළදා කරඬුව වඩමවන මංගල හස්ති රාජයාගේ ගමන් විලාසය ගජගා වන්නමෙන් නිරූපණය වේ."),
        q("'තුරඟා වන්නම' මගින් වර්ණනා කෙරෙනුයේ කවර සිදුවීමක් හා සත්ත්වයෙකුද?", "සිද්ධාර්ථ කුමරු කන්ථක අසු පිට නැගී මහාභිනිෂ්ක්‍රමණය කිරීම", "වඳුරෙකු ගස් මත පැනීම", "සර්පයෙකු බඩගා යෑම", "උකුස්සෙකු පියාසර කිරීම", "අශ්වයෙකුගේ ගමන් තාලය හා කන්ථක අශ්වයාගේ කතා පුවත තුරඟා වන්නමේ අන්තර්ගත වේ."),
        q("'උකුසා වන්නම' සහ 'මයුරා වන්නම' යන දෙකටම පදනම් වී ඇති පොදු තේමාව කුමක්ද?", "පක්ෂීන්ගේ චලන විලාසය හා සොබා සෞන්දර්යය", "මුහුදු යාත්‍රා කිරීම", "පතල් කැණීම", "කුඹුරු හෑම", "උකුස්සාගේ හා මොනරාගේ අභිමානවත් පියාසැරි හා නර්තන ලීලා මෙම වන්නම්වලින් ගැයේ."),
        q("'හනුමා වන්නම' ගායනා කිරීමේදී මතු කරන ප්‍රධාන නාට්‍යමය ලක්ෂණය කුමක්ද?", "වඳුරාගේ කඩිසර හා විකට චලන රිද්මය", "ගැඹුරු ශෝකජනක වැලපීම", "නිහඬ භාවනා ඉරියව්ව", "මන්දගාමී පාරු පැදීම", "රාමායණයේ හනුමාන්ගේ වීර හා කඩිසර ගතිලක්ෂණ අනුව රිද්මයානුකූලව මෙය ගැයේ."),
        q("උඩරට දහඅට වන්නම් ආරම්භයේදී සෑම වන්නමකටම පාහේ ගයනු ලබන තාල පදය කුමක්ද?", "තානම (තන තම්දන නා ආදී ලෙස)", "ඛ්‍යාල් ආලාපය", "පූර්ව නූර්ති ගීය", "කපිරිඤ්ඤා කෝරසය", "වන්නමේ නාද රටාව හා ලය හඳුන්වා දීම සඳහා මුලින්ම 'තානම' ගායනා කෙරේ."),
        q("වන්නමක් ගායනා කරන පිළිවෙළ අනුව 'තානමට' පසුව ගායනා කරනු ලබන කොටස කුමක්ද?", "කවිය හා කස්තිරම (බෙර පද)", "අවසන් ආශිර්වාදය", "සර්ගම් කොටස", "මධ්‍ය ඛාලි", "තානමෙන් පසු වන්නම් කවිය ගයා, කස්තිරම, සීරුමාරුව සහ අඩව්ව ඉදිරිපත් කෙරේ."),
        q("වන්නම් 18ට අමතරව ගැමි කලාවේ ප්‍රචලිත 'සිව්පද' වන්නම් හා සබරගමු වන්නම් ගැන සඳහන් වන කෘතිය කුමක්ද?", "දේශීය නර්තන හා ජන සංගීත මූලාශ්‍ර", "සාම වේදය", "නාට්‍ය ශාස්ත්‍රය", "බෘහද්දේශී", "උඩරට වන්නම් 18 මෙන්ම සබරගමු හා පහතරට සම්ප්‍රදායන්හිද වන්නම් විශේෂ පවතී."),
        q("පාරු කවියක බොහෝ විට අන්තර්ගත වන සංස්කෘතික හා භූගෝලීය තොරතුරු මොනවාද?", "කළු ගඟ, කැලණි ගඟ හා බෙන්තර ගඟ ආශ්‍රිත තොටුපළ හා ගමන් විස්තර", "හිමාල කඳුවැටියේ හිම පතනය", "මුහුදු යාත්‍රිකයන්ගේ යුද්ධ", "මැණික් පතල් ඇතුළත උමං", "දියමං දිගේ බඩු ප්‍රවාහනය කළ තොටියන් තම ගමන් මග හා පරිසරය පාරු කවිවල ගැයූහ."),
        q("'කළු ගඟ දෙබෑ කරගෙන ඔරු පැද යන්නේ' වැනි ජන කවි අයත් වන්නේ කුමන ශ්‍රම කවි ගණයටද?", "පාරු හා ඔරු කවි ගණයට", "බම්බර කවි ගණයට", "කමත් කවි ගණයට", "රබන් කවි ගණයට", "ගංගා ආශ්‍රිත ප්‍රවාහන ජීවිතයෙන් බිහිවූ පාරු කවි මෙම ගණයට වැටේ."),
        q("බම්බර කවි ගායනා කිරීමේදී එම කවිවල පවතින සුවිශේෂී ශෝකී හෝ බැගෑපත් භාවයට හේතුව කුමක්ද?", "ප්‍රපාතවල එල්ලී මී වද කැඩීමේ ජීවිත අවදානම හා දේව ආරක්ෂාව පැතීම", "මිතුරන් සමඟ සතුටින් විහිළු කිරීම", "නැටුම් පුහුණුවීම", "රජුට සුබ පැතීම", "ගල්පරවල වැල් ඉණිමගක එල්ලී සිටින අය තම ආරක්ෂාව හා පවුල සිහි කරමින් ගයති."),
        q("ගොයම් පාගන කමතේදී ගැමියන් භාවිත කරන 'කමත් භාෂාව' ඇතුළත් කවි මොනවාද?", "කමත් කවි / ගොන් කවි", "කරත්ත කවි", "පතල් කවි", "මුහුදු හෝයි පද", "ගොයම් කොළ පාගන විට බැත, ගොනුන් හා පරිසරය ගැන කමත් බසින් කවි ගැයේ."),
        q("කරත්ත කවිවල බහුලව සඳහන් වන 'හපුතලේ කන්ද', 'පස්සර', 'ගලගෙදර' වැනි ස්ථානවලින් හෙළිවන්නේ කුමක්ද?", "පුරාණ කරත්ත වෙළඳ ගමන් මාර්ග හා කඳු තරණය", "මුහුදු වරාය ආශ්‍රිත ඉදිකිරීම් කටයුතු", "නූතන ගුවන් ගමන් පථ හා සැලසුම්", "රජමාලිගාවේ පැවති රාජකීය උත්සව", "කඳුකර හා තැනිතලා අතර බඩු ගෙන ගිය ගැල්කරුවන්ගේ අත්දැකීම් එහි රැඳී ඇත."),
        q("'තණ්ඩලේ දෙන්නා දෙපොළේ දක්කනවා' යන සුප්‍රකට කරත්ත කවියෙන් කියැවෙන ප්‍රධාන සිතිවිල්ල කුමක්ද?", "කඳු නගින ගොනුන් කෙරෙහි ගැල්කරු තුළ ඇති කරුණාව හා තම දුක", "ගොනුන්ට කෝපයෙන් බැණ වැදීම", "නගරයේ වෙළඳපොළ වර්ණනා කිරීම", "නැටුමකට ආරාධනා කිරීම", "ගොනුන් විඳින වෙහෙස දැක ගැල්කරු තුළ ඇතිවන අනුකම්පාව මෙම කවියේ ප්‍රකටය."),
        q("පතල් කවිවලදී 'මහ පොළොවෙන් ලැබෙන මැණික්' වෙනුවෙන් පතල්කරුවන් කවි මගින් කුමක් ප්‍රාර්ථනා කරයිද?", "දෙවි දේවතාවුන්ගේ ආරක්ෂාව, සාමූහික ශක්තිය හා සාර්ථක අස්වැන්න", "රජුගෙන් දඬුවම් නොලැබීම", "වර්ෂාව අධික වීම", "පතල කඩා වැටීම", "අඳුරු පතල තුළ බිය දුරු කර ගැනීමට හා ආරක්ෂාව පතා දේව ආශිර්වාදය ඉල්ලා ගයති."),
        q("ගැමි දරු නැළවිලි ගීතයක් වන 'දොයි දොයි දොයිය බබා - බයි බයි බයිය බබා' ගායනයේ තාල ලක්ෂණය කුමක්ද?", "තොටිල්ල පැද්දෙන රිද්මයට ගැළපෙන මෘදු සමපද ලය", "වේගවත් යුද බෙර තාලය", "මාත්‍රා 14 ධමාර් තාලය", "නාඩගම් මද්දල කස්තිරම", "තොටිල්ල ඉදිරියට හා පසුපසට චලනය වන ලයට සමාන මෘදු හා ඒකාකාරී රිද්මයක් මෙහි ඇත."),
        q("සිංහල අවුරුදු ක්‍රීඩා හා බැඳුණු 'එළුවන් කෑම', 'ඔලිඳ කෙළිය', 'මේවර කෙළිය' වැනි ක්‍රීඩා සමඟ ගැයෙන ගීත කවරේද?", "ජන ක්‍රීඩා ගීත (ක්‍රීඩා කවි)", "පැල් කවි", "පසන් ගී", "මංගල අෂ්ටක", "ගැමි දරුවන් හා තරුණ තරුණියන් ජන ක්‍රීඩාවල නියැළෙමින් මෙම රිද්මයානුකූල ගී ගැයූහ."),
        q("'ඔලිඳ තිබෙන්නේ කොයි කොයි දේසේ' යන ගීතය ගායනා කරනු ලබන්නේ කවර ජන ක්‍රීඩාවක් අතරතුරද?", "ඔලිඳ කෙළිය", "ලී කෙළි ක්‍රීඩාව", "කඹ ඇදීම", "පංච කෙළිය", "පුවරු ක්‍රීඩාවක් වන ඔලිඳ කෙළියේදී ඉත්තන් අල්ලමින් කාන්තාවෝ මෙම ගීතය ගයති."),
        q("කාන්තාවන් වට වී රබාන වටා හිඳ වයන 'රබන් පද' අතර 'තකදොං තරිකිට' වැනි ශබ්ද හඳුන්වන්නේ කෙසේද?", "රබන් අක්ෂර හෙවත් රබන් පද", "රාග ආලාප ස්වර", "බටහිර කෝඩ්ස්", "නූර්ති දෙබස්", "රබන් සම මත ඇඟිලිවලින් හා අත්ලෙන් ගැසීමේදී උපදින ශබ්ද අනුකරණයෙන් රබන් පද තැනී ඇත."),
        q("ජන සංගීතයේදී 'තාලම්පට' වාදනය කරමින් පේළියට හෝ රවුමට නටමින් ගයන ජන නර්තන අංගයක් කුමක්ද?", "සවරම් නැටුම / ලී කෙළි නැටුම", "කෝලම් යක් නැටුම", "සොකරි නාටකය", "වන්නම් පෙළපාලිය", "පාසල් හා ගැමි උත්සවවල ලී කෙළි හා පන්තේරු නැටුම් සාමූහිකව ඉදිරිපත් කෙරේ."),
        q("කළගෙඩි පිඹීම හා අතින් අත මාරු කර උඩ දැමීම සමඟ ගැයෙන 'කළගෙඩි සැහැල්ල' ප්‍රචලිත වී ඇත්තේ කුමන සමාජ සිදුවීමකද?", "විවේක කාලවල හා සාම්ප්‍රදායික ගැමි උත්සවවල", "පාර්ලිමේන්තු රැස්වීම්වල", "වෙළඳ දැන්වීම්වල", "ශෝකාකූල අවමංගල්‍යවල", "ගැමි කතුන්ගේ කලා කුසලතා හා විනෝදය පෙන්වන උත්සවාකාර ජන කලා අංගයකි."),
        q("ශ්‍රී ලංකාවේ දේශීය ජන ගීවල 'සප්ත ස්වර සියල්ලම' යෙදීම වෙනුවට බොහෝ විට යෙදෙන්නේ ස්වර කීයක් පමණද?", "ස්වර 3 සිට 5 දක්වා සීමිත ස්වර ගණනකි", "විකෘති ස්වර 12ම එක් කවියක යෙදේ", "සප්තක 3ක ස්වර 21ක් යෙදේ", "එක් ස්වරයක් පමණක් යෙදේ", "ජන ගීයේ සරල බව රැකෙන්නේ ස-රි-ග-ම-ප වැනි සීමිත ස්වර කලාපයක පිහිටන බැවිනි."),
        q("පාරම්පරික ගැමි 'ශාන්තිකර්ම' ගායනා අතර ගායකයන් රෝගියාට සෙත් පතා කියන කොටස කුමක්ද?", "ආශිර්වාද කවි හා සැහැලි", "නූර්ති සින්දු", "ග්‍රැමෆෝන් සරල ගී", "බයිලා ගීත", "ගම්මඩු, සූනියම් හා රට යකුම වැනි ශාන්තිකර්මවල ආතුරයාට සෙත් පතා ආශිර්වාද කවි ගැයේ."),
        q("ශාන්තිකර්ම ගීත ගායනයේදී බෙර හඬ සමඟ එක්වන 'ගයන හා නටන' යක්දෙස්සන් භාවිත කරන පද්‍ය ආකෘතිය කුමක්ද?", "සැහැලි, කන්නලව් සහ අෂ්ටක", "ඉංග්‍රීසි පද්‍ය", "උර්දු ගසල්", "හින්දි දෝහා", "දේව ආරාධනා හා පුවත් පැවසීමට කන්නලව් හා සැහැලි සාම්ප්‍රදායික තාලයට ගැයේ."),
        q("'සූනියම් යාගය' හෝ 'රට යකුම' වැනි ශාන්තිකර්මවලදී ගැයෙන ගීත කවර ප්‍රදේශයකට අයත් ජන සංගීත උරුමයක්ද?", "පහතරට සම්ප්‍රදායට", "උතුරු යාපනය සම්ප්‍රදායට", "බටහිර යුරෝපීය සම්ප්‍රදායට", "උත්තර භාරතීය ඝරානාවට", "රට යකුම හා සන්නි යකුම දකුණු ලක පහතරට සම්ප්‍රදායේ ප්‍රධාන ශාන්තිකර්ම වේ."),
        q("'පහන් මඩු' හා 'ගම්මඩු' ශාන්තිකර්මවල ප්‍රධාන වශයෙන් ගායනා කර පූජා පවත්වන්නේ කවර දෙවියන්ටද?", "පත්තිනි දේවිය ප්‍රධාන දෙවිවරුන්ට", "ග්‍රීක දෙවිවරුන්ට", "නෝර්ස් දෙවිවරුන්ට", "රෝම දෙවිවරුන්ට", "ගමට සෙත් පතා කෙරෙන ගම්මඩුවල පත්තිනි දේවතාවියගේ ගුණ කවි හා පන්තිස් කෝල්මුර ගැයේ."),
        q("උඩරට 'කොහොඹා කංකාරිය' ශාන්තිකර්මයේදී ගායනා කරන පැරණි කවි හා යාතිකා සඳහා වයන බෙරය කුමක්ද?", "ගැටබෙරය", "යක්බෙරය", "තබ්ලාව", "මද්දලය", "උඩරට කොහොඹා කංකාරියේ පූජා වතාවත් හා නර්තන ගැටබෙර නාදයෙන් මෙහෙයවේ."),
        q("සබරගමු පළාතට ආවේණික 'පහන් මඩු' හා 'මල් බලි' ශාන්තිකර්මවලදී ප්‍රධාන වශයෙන් වයන බෙරය කුමක්ද?", "දවුල", "තබ්ලාව", "උඩැක්කිය පමණක්", "බොංගෝ බෙරය", "සබරගමු නර්තන හා ශාන්තිකර්ම සම්ප්‍රදායේ ප්‍රධාන තාල භාණ්ඩය දවුලයි."),
        q("සිංහල ජන සංගීතයේදී 'පිරිත්' සජ්ඣායනය හා ජන ගී අතර දක්නට ලැබෙන පොදු ස්වර සබඳතාව කුමක්ද?", "කෙටි ස්වර පරාසයක් තුළ ශාන්ත හා ඒකාග්‍රතා හඬින් ගැයීම", "වේගවත් නර්තන තාල තිබීම", "කෝමල ස්වර 12ක් භාවිත කිරීම", "විදුලි වාද්‍ය භාණ්ඩ භාවිතය", "මන්ද්‍ර හා මධ්‍ය ස්වර 3–4ක සංයමශීලී ව්‍යාප්තිය ජන කවි හා පිරිත් ස්වර අතර සමානකම් පෙන්වයි."),
        q("'දහඅට වන්නම්' වලින් වැඩි ප්‍රමාණයක් නම් කර ඇත්තේ කවර දේවල් අනුවද?", "සත්ත්ව චලන සහ පෞරාණික කතා පුවත් අනුව", "යුරෝපීය නගර නම් අනුව", "ඉන්දියානු රාග නම් අනුව", "බටහිර වාද්‍ය භාණ්ඩ අනුව", "ගජගා, තුරඟා, මයුරා, සිංහරාජ, හංසා ආදී වශයෙන් සතුන් හා කතා පුවත් මුල්කර නම් තබා ඇත."),
        q("'කිරලා වන්නම', 'මූසලඩි වන්නම' සහ 'සිංහරාජ වන්නම' යන ඒවා අයත් වන්නේ කුමන කලාංගයටද?", "උඩරට සම්භාව්‍ය දහඅට වන්නම්වලට", "නූර්ති නාට්‍ය ගීතවලට", "මුහුදු ධීවර කවිවලට", "පාර්සි නාට්‍ය ගීවලට", "උඩරට නර්තන හා ගායන සම්ප්‍රදායේ දහඅට වන්නම් පෙළට මේවා ඇතුළත් වේ."),
        q("'විරිදු' ගායන කලාවේදී ගායකයා ක්ෂණිකව (හිටිවනම) කවි ගොතා ගැයීමේදී තාලය තබාගැනීමට භාවිත කරන භාණ්ඩය කුමක්ද?", "අත් රබාන", "සිතාරය", "බන්සූරිය", "තම්බුරාව", "අත් රබාන වයමින් කාලීන සිදුවීම් හෝ කතා පුවත් හිටිවන කවියෙන් ගැයීම විරිදු කලාවයි."),
        q("ශ්‍රී ලංකාවේ 'විරිදු' ගායනා තුළ කැපී පෙනෙන සුවිශේෂී කුසලතාව කුමක්ද?", "එළිසමය රැක ගනිමින් ක්ෂණිකව තාලයට පද නිර්මාණය කිරීම", "බටහිර ස්වර ප්‍රස්තාර කියවීම", "හින්දුස්ථානි තාන ගැයීම", "වෙස්මුහුණු පැළඳ නැටීම", "අවස්ථානුකූලව වහාම කවි පද බැඳ තාලයට ගැයීම විරිදු ශිල්පියාගේ දක්ෂතාවයයි."),
        q("ශ්‍රී ලංකාවේ 'තාලම්පට' හා සමානව කැඩුණු පොල්කටු හෝ උණ බම්බු කැබලි යොදා ගැමි රිද්ම මවන අවස්ථා මොනවාද?", "සමහර ළමා හා ගැමි ක්‍රීඩා ගායනාවලදී", "රාජකීය හේවිසි පූජාවලදී පමණක්", "ශාස්ත්‍රීය ඛ්‍යාල් ප්‍රසංගවල", "බටහිර සිම්ෆනි වාදනවල", "ගැමි දරුවන් පරිසරයේ ස්වාභාවික ද්‍රව්‍ය යොදාගෙන රිද්මයානුකූලව සෙල්ලම් ගී ගැයූහ."),
        q("සිංහල ජන සංගීතයේ 'අත්වැල් ගායනය' (Call and Response) වඩාත් පැහැදිලිව දක්නට ලැබෙන්නේ කුමන කවිවලද?", "ගොයම් කවි, නෙළුම් කවි සහ ඔරු පාරු කවිවල", "හුදෙකලා පැල් කවියේ පමණක්", "සරල ගී ඒකල ගායනයේ", "ධ්‍රැපද් ආලාපයේ", "ප්‍රධාන ගායකයා කියන පදයට අනෙක් කණ්ඩායම එක හඬින් පිළිතුරු පද ගැයීම නෙළුම් හා ගොයම් කවිවල දක්නට ලැබේ."),
        q("ශ්‍රී ලංකාවේ 'සීපද' හෙවත් සිව්පද කවි සාමාන්‍යයෙන් පේළි කීයකින් සමන්විත වේද?", "පේළි 4 කින් (පාද 4)", "පේළි 2 කින්", "පේළි 10 කින්", "පේළි 16 කින්", "සමාන මාත්‍රා හෝ එළිසමය ඇති පාද හතරකින් යුත් කවිය සීපද හෙවත් සිව්පද නම් වේ."),
        q("සිංහල සීපද ගායනයේදී එකම කවිය විවිධ ප්‍රදේශවල වෙනස් නාද මාලාවලින් ගැයීමට හේතුව කුමක්ද?", "මුඛ පරම්පරාගතව පැමිණීම හා ප්‍රාදේශීය ගායන හුරුව", "ස්වර ප්‍රස්තාර පොත් වැරදීම", "රජයෙන් තහනම් කිරීම", "විදේශීය භාණ්ඩ වෙනස් වීම", "කටින් කට පැමිණෙන විට ඒ ඒ පළාත්වල සංස්කෘතික හුරුව අනුව තනු වෙනස් වී ඇත."),
        q("'කුරහන් කවි' ගායනා කරනු ලබන්නේ කුමන කෘෂිකාර්මික කටයුත්තක් සමඟද?", "හේන් ගොවිතැනේ කුරහන් කැපීම හා ඇඹරීමේදී", "මුහුදේ මසුන් ඇල්ලීමේදී", "මැණික් ගැරීමේදී", "ගල් කැඩීමේදී", "වියළි කලාපයේ හේන් ගොවිතැන හා කුරහන් ගලේ ඇඹරීමේදී කාන්තාවෝ කුරහන් කවි ගැයූහ."),
        q("ගැමි කාන්තාවන් කුරහන් ගලේ ඇඹරීමේදී ගයන කවිවල රිද්මය සැකසෙන්නේ කුමක් අනුවද?", "කුරහන් ගල කරකවන වෘත්තාකාර අත් චලනයේ වේගය අනුව", "තබ්ලාවේ ත්‍රිතාලය අනුව", "ගැටබෙරයේ කස්තිරම අනුව", "පියානෝවේ වේගය අනුව", "කුරහන් ගල කරකවන ඒකාකාරී රිද්මයට ගැළපෙන සේ කුරහන් කවි ගැයේ."),
        q("දේශීය ජන ගී අතරින් 'තේවාව' හා බැඳුණු පූජනීය ගායනාවක් නොවන්නේ කුමක්ද?", "කපිරිඤ්ඤා ගීත", "තුන් සරණය", "බුදු ගුණ කවි", "මංගල ගාථා", "කපිරිඤ්ඤා යනු විනෝදාස්වාදය හා නර්තනය සඳහා ගැයෙන පෘතුගීසි ආභාසිත ගීතයකි."),
        q("ශ්‍රී ලංකාවේ දකුණු පළාතේ ගැමි කතුන් රබන් ගසමින් ගයන 'වැට බඳින රබන් පද' කුමන අවස්ථාවක ගැයේද?", "සිංහල අවුරුදු හා මංගල උත්සවවල", "පාසල් විභාග ශාලාවල", "වැඩිහිටි රැස්වීම්වල පමණක්", "කාර්යාල රැස්වීම්වල", "අලුත් අවුරුදු සමයේ ගැමි නිවෙස්වල විනෝදය පිණිස විවිධ රබන් පද වාදනය කෙරේ."),
        q("දේශීය ජන ගීයේ 'අන්තර්ගතය' අධ්‍යයනය කිරීමෙන් සිසුවෙකුට දැනගත හැකි වැදගත්ම දෙය කුමක්ද?", "පැරණි ගැමි සමාජයේ ජීවන රටාව, සිරිත් හා හැඟීම්", "නූතන පරිගණක හා විදුලි තාක්ෂණ ක්‍රම", "විදේශීය රටවල දේශගුණික වෙනස්වීම්", "ඉන්දියානු උත්තර භාරතීය රාග ගණන", "ජන ගී යනු අතීත ගැමි ජනතාවගේ සැබෑ ජීවිතය පිළිබිඹු කරන කැඩපතකි."),
        q("ජන සංගීතය වත්මන් පාසල් හා ප්‍රසංග වේදිකාවට ගෙන ඒමේදී එහි 'සම්ප්‍රදායික අනන්‍යතාව' රැකගත යුත්තේ ඇයි?", "ජාතික සංස්කෘතික උරුමය නොනැසී අනාගත පරපුරට දායාද කිරීමට", "අනෙක් සංගීත ක්‍රම තහනම් කිරීමට", "තබ්ලාව භාවිතය නතර කිරීමට", "වෙනත් රටවලට විකිණීමට", "අපේ ජාතික අනන්‍යතාව රැඳී ඇත්තේ දේශීය ජන සංගීත උරුමය තුළ බැවිනි."),
        q("'දොළොස් මහේ රබන් පදය' හෝ 'බුදු ගුණ කවි' වැනි දේශීය නිර්මාණ තුළ දක්නට ලැබෙන ප්‍රධාන වටිනාකම කුමක්ද?", "ආගමික භක්තිය, කාලගුණ රටා හා සාරධර්ම මතු කිරීම", "විදේශීය වෙළඳ නාම ප්‍රචාරණය", "සංකීර්ණ ගණිත සූත්‍ර ඉගැන්වීම", "විකෘති ස්වර 12 පුහුණු කිරීම", "ගැමි කලාව සැමවිටම මානව දයාව හා සාරධර්ම සමඟ බැඳී පවතී.")
    )
}
